interface Settings {
  readonly theme: string;
  fontSize?: number;
}

function apply(s: Readonly<Settings>) {
  // s.theme = 'x'; // compile error
  return s.fontSize ?? 14;
}

console.log(apply({ theme: 'dark', fontSize: 16 }));
console.log(apply({ theme: 'light' }));

