function topTwo(nums: number[]): number[] {
  // sort() mutates the input array!
  return nums.sort((a, b) => b - a).slice(0, 2);
}

const scores = [3, 1, 2];
console.log(topTwo(scores));
console.log(scores); // original order is gone: [3, 2, 1]

solution.code:
function topTwo(nums: readonly number[]): number[] {
  return [...nums].sort((a, b) => b - a).slice(0, 2);
}

const scores = [3, 1, 2];
console.log(topTwo(scores));
console.log(scores); // unchanged: [3, 1, 2]

interface Config { url: string; timeout?: number; retries?: number; }
interface FullConfig { url: string; timeout: number; retries: number; }

function withDefaults(cfg: Readonly<Config>): FullConfig {
  return {
    url: cfg.url,
    timeout: cfg.timeout ?? 5000,
    retries: cfg.retries ?? 3,
  };
}

console.log(withDefaults({ url: '/api' }));
console.log(withDefaults({ url: '/api', timeout: 1000 }));
